<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$rows=$pdo?$pdo->query('SELECT a.action,a.details,a.created_at,u.email FROM admin_activity a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Activity</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Admin Activity</h1><p><a href="dashboard.php">Dashboard</a></p><div class="card"><table style="width:100%"><tr><th>User</th><th>Action</th><th>Details</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['email']??'Unknown')?></td><td><?=e($r['action'])?></td><td><?=e($r['details']??'')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">No activity recorded.</p><?php endif;?></div></main></body></html>
